head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        placeholder: wf_sample.getObj("con_placeholder").getValue(),
        placeholderLocaleRef: wf_sample.getObj("con_placeholderLocaleRef").getText(),
        useLocale: wf_sample.getObj("con_useLocale").getText(),
    };

    let cList = $c.gcm.createCList(properties);

    // textarea 생성 (placeholder 확인을 위해 입력값은 비움)
    await $c.gcm.createBasicTextArea(cList, 'ev:onclick="scwin.target1_onclick"');
    target1.setValue("");
}
